/// <summary>
/// Bug 306156: [MS] CB201 - Customer rebates: Attribute Filtering Logic Not Correct - MS SR # 2410100030001214
/// Refactor
/// </summary>
[METRebateOrAttribute(HeaderLines_IT::Header)]
final class METTAMRebateQueryBuilderORAttributes_Header extends METTAMRebateQueryBuilderORAttributes
{
    QueryBuildDataSource metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup, metqbdsGUPEcoResInstanceAttributeValuesBannerGroup;
    QueryBuildDataSource metqbdsCustomerInstanceValue;

}

Method.Source:
/// <summary>
/// Initialize the class for header attributes
/// </summary>
protected void init()
{
    pricingRuleRefRecId = rebateTable.PricingRuleHeader;
    rangeFieldId = rebateQueryBuilder.accountJourTableFieldId();
}

/// <summary>
/// Get the name of the query build data source (qbds) for the given attribute link
/// </summary>
/// <param name = "_attributeLink">The attribute link object</param>
/// <returns>The name of the qbds as a string</returns>
protected str getQbdsName(GUPPricingAttributeLink _attributeLink)
{
    str qbdsName;
    qbds = query.dataSourceTable(rebateQueryBuilder.journalTable());
    QueryBuildDataSource qbdsCustTable = query.dataSourceTable(tableNum(CustTable));   
    FieldId accountFieldId = rebateQueryBuilder.accountJourTableFieldId();

    // If there are muliple complex attribute, you have to join all datasource here to build the query range correctly.
    // In this example, I only handle SalesTable and CustTable as attribute source for header rule.
    if (_attributeLink.SourceName == METConstants::SalesTable)
    {
        qbdsName = qbds.name();
    }
    else if (_attributeLink.SourceName == METConstants::CustTable)
    {
        if (!qbdsCustTable)
        {
            qbdsCustTable = qbds.addDataSource(tableNum(CustTable));
            qbdsCustTable.addLink(accountFieldId, fieldNum(CustTable, AccountNum));
            qbdsCustTable.addSelectionField(fieldNum(CustTable, AccountNum));
            qbdsCustTable.relations(false);
            qbdsCustTable.joinMode(JoinMode::InnerJoin);
            qbdsCustTable.fetchMode(QueryFetchMode::One2One);
        }

        qbdsName = qbdsCustTable.name();
    }
    else if (_attributeLink.SourceName == METConstants::GUPPricingAttributeProviderCustomerAttribute)
    {
        if (!metqbdsCustomerInstanceValue)
        {
            metqbdsCustomerInstanceValue = qbds.addDataSource(tableNum(CustomerInstanceValue));
            metqbdsCustomerInstanceValue.addLink(accountFieldId, fieldNum(CustomerInstanceValue, AccountNum));

            int fieldDataAreaId;

            // TAMRebateQueryBuilderSalesDeliveryNote and TAMRebateQueryBuilderSalesInvoice are internal :/
            if (rebateTable.SourceType == TAMRebateSourceType::Ordered)
            {
                fieldDataAreaId = fieldNum(SalesTable, DataAreaId);
            }
            else if (rebateTable.SourceType == TAMRebateSourceType::Delivery)
            {
                fieldDataAreaId = fieldNum(CustPackingSlipJour, DataAreaId);
            }
            else
            {
                fieldDataAreaId = fieldNum(CustInvoiceJour, DataAreaId);
            }

            metqbdsCustomerInstanceValue.addLink(fieldDataAreaId, fieldNum(CustomerInstanceValue, CustomerDataAreaId));
            metqbdsCustomerInstanceValue.addSelectionField(fieldNum(CustomerInstanceValue, RecId));
            metqbdsCustomerInstanceValue.relations(false);
            metqbdsCustomerInstanceValue.joinMode(JoinMode::InnerJoin);
            metqbdsCustomerInstanceValue.fetchMode(QueryFetchMode::One2One);
        }

        if (_attributeLink.AttributeName == METConstants::CustomerSuperGroup
        && !metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup)
        {
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup = metqbdsCustomerInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addLink(fieldNum(CustomerInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.relations(false);

            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.joinMode(JoinMode::OuterJoin);
            metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.fetchMode(QueryFetchMode::One2One);
            qbdsName = metqbdsGUPEcoResInstanceAttributeValuesCustSuperGroup.name();
        }

        // Have to split data source in case we get a mix of inclusion/exclusion for customer super group and banner group
        if (_attributeLink.AttributeName == METConstants::BannerGroup
        && !metqbdsGUPEcoResInstanceAttributeValuesBannerGroup)
        {
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup = metqbdsCustomerInstanceValue.addDataSource(tableNum(GUPEcoResInstanceAttributeValuesView));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addLink(fieldNum(CustomerInstanceValue, RecId), fieldNum(GUPEcoResInstanceAttributeValuesView, RecId));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeName));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, AttributeTypeName));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, TextValue));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.addSelectionField(fieldNum(GUPEcoResInstanceAttributeValuesView, BooleanValue));
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.relations(false);

            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.joinMode(JoinMode::OuterJoin);
            metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.fetchMode(QueryFetchMode::One2One);
            qbdsName = metqbdsGUPEcoResInstanceAttributeValuesBannerGroup.name();
        }

    }

    return qbdsName;
}
